'use strict';
const $=id=>document.getElementById(id);
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const norm=v=>String(v??'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase().trim();
const uid=()=> 'own:'+Date.now().toString(36)+Math.random().toString(36).slice(2,8);
const qty=n=>Number(Number(n).toFixed(2)).toLocaleString('hu-HU');
const dateKey=d=>[d.getFullYear(),String(d.getMonth()+1).padStart(2,'0'),String(d.getDate()).padStart(2,'0')].join('-');
const today=()=>dateKey(new Date());
const dayNames=['H','K','Sze','Cs','P','Szo','V'];
const dayLong=['Hétfő','Kedd','Szerda','Csütörtök','Péntek','Szombat','Vasárnap'];
const baseDefaults=()=>({schema:2,people:2,theme:'auto',favorites:[],ratings:{},notes:{},collections:[],custom:[],history:[],cooked:{},scores:{},plan:{},shop:[],pantry:[],pantryItems:[],exclude:[],smart:true,mode:'grid',savedSides:{}});
const dict=new Map(recipes.map(r=>[String(r.id),r]));
const clamp=(n,a,b)=>Math.min(b,Math.max(a,Number.isFinite(Number(n))?Number(n):a));
const hasOwn=(o,k)=>Object.prototype.hasOwnProperty.call(o,k);
const isObj=x=>x&&typeof x==='object'&&!Array.isArray(x);
const asText=(s,limit=200)=>typeof s==='string'?s.slice(0,limit):'';
const strArray=(a,limit=10000)=>Array.isArray(a)?a.filter(x=>typeof x==='string'||typeof x==='number').slice(0,limit).map(x=>String(x).slice(0,200)):[];
const recipeId=x=>typeof x==='string'||typeof x==='number'?String(x):'';
const ownId=x=>/^own:[a-z0-9]+$/i.test(x);
const allowedUnits=['g','kg','ml','l','db','ek','tk','csipet','gerezd','szál','szelet','adag','csomag','marék'];
function validIngredient(i){return isObj(i)&&typeof i.name==='string'&&i.name.trim()&&Number.isFinite(Number(i.qty))&&Number(i.qty)>0&&Number(i.qty)<100000&&typeof i.unit==='string'}
const cleanIng=i=>({name:asText(i.name,100).trim(),qty:Number(i.qty),unit:asText(i.unit,20)});
const cuisines=[...new Set(recipes.map(r=>r.cuisine))].sort((a,b)=>a.localeCompare(b,'hu'));
const proteins=[...new Set(recipes.map(r=>r.protein))].sort((a,b)=>a.localeCompare(b,'hu'));
const types=['Főétel','Leves','Reggeli','Desszert','Előétel','Saláta','Köret','Sütemény'];
const methods=['Tűzhely','Sütő','Forrólevegős sütő','Grill','Sütés nélkül'];
const difficulties=['Könnyű','Közepes','Haladó'];
const holidays=[...new Set(recipes.flatMap(r=>r.holidays||[]))].sort((a,b)=>a.localeCompare(b,'hu'));
const bakingTastes=['Édes','Sós'];
const bakingKinds=[...new Set(recipes.filter(r=>r.bakery).map(r=>r.bakery.kind))].sort((a,b)=>a.localeCompare(b,'hu'));
const bakingFlavors=[...new Set(recipes.filter(r=>r.bakery).map(r=>r.bakery.flavor))].sort((a,b)=>a.localeCompare(b,'hu'));
const expiryTypes=['Fogyasztható','Minőségét megőrzi','Nem ismert'];
function validDate(v){if(typeof v!=='string'||!/^\d{4}-\d{2}-\d{2}$/.test(v))return false;const d=new Date(v+'T00:00:00Z');return Number.isFinite(+d)&&d.toISOString().slice(0,10)===v&&v>='1900-01-01'&&v<='2199-12-31'}
function expiryDays(v){return validDate(v)?Math.round((Date.parse(v)-Date.parse(today()))/86400000):Infinity}
function panId(){return 'pan:'+Date.now().toString(36)+Math.random().toString(36).slice(2,10)}
function cleanPantry(x){if(!isObj(x)||!asText(x.name,120).trim())return null;return {id:/^pan:[a-z0-9]+$/.test(x.id)?x.id:panId(),name:asText(x.name,120).trim(),alias:asText(x.alias,120).trim(),qty:clamp(x.qty,0.01,100000),unit:asText(x.unit,20),expiry:validDate(x.expiry)?x.expiry:'',expiryType:expiryTypes.includes(x.expiryType)?x.expiryType:'Nem ismert',added:validDate(x.added)?x.added:today()}}
function normalizePantry(items,legacy){const a=Array.isArray(items)?items.slice(0,2000).map(cleanPantry).filter(Boolean):strArray(legacy,500).map(name=>cleanPantry({name,alias:name,qty:1,unit:'db'})).filter(Boolean);const seen=new Set();for(const x of a){if(seen.has(x.id))x.id=panId();seen.add(x.id)}return a}
function activePantry(items){return [...new Set(items.filter(x=>expiryDays(x.expiry)>=0).map(x=>x.alias||x.name))]}
function refreshPantry(){data.pantry=activePantry(data.pantryItems)}
function sanitizeRecipe(r){if(!isObj(r)||!ownId(r.id)||!asText(r.name,160).trim()||!Array.isArray(r.ing)||!r.ing.length||!r.ing.every(validIngredient)||!Array.isArray(r.steps)||!r.steps.some(x=>asText(x,2000).trim()))return null;
return {id:r.id,name:asText(r.name,160).trim(),cuisine:cuisines.includes(r.cuisine)?r.cuisine:'Nemzetközi',protein:proteins.includes(r.protein)?r.protein:'Egyéb',side:'Nincs',time:clamp(r.time,5,720),base:clamp(r.base,1,24),type:types.includes(r.type)?r.type:'Főétel',method:methods.includes(r.method)?r.method:'Tűzhely',difficulty:difficulties.includes(r.difficulty)?r.difficulty:'Közepes',holidays:strArray(r.holidays,20).filter(x=>holidays.includes(x)),...(isObj(r.bakery)&&bakingTastes.includes(r.bakery.taste)&&bakingKinds.includes(r.bakery.kind)&&bakingFlavors.includes(r.bakery.flavor)?{bakery:{taste:r.bakery.taste,kind:r.bakery.kind,flavor:r.bakery.flavor}}:{}),origin:'saját',swap:false,separate:false,spicy:!!r.spicy,ing:r.ing.slice(0,100).map(cleanIng),steps:r.steps.slice(0,80).map(x=>asText(x,2000).trim()).filter(Boolean)}}
function sanitizeData(input){if(!isObj(input)||input.schema!==2)throw Error('Nem támogatott mentési formátum.');
const o=baseDefaults();o.people=clamp(input.people,1,24);o.theme=['auto','light','dark'].includes(input.theme)?input.theme:'auto';o.smart=input.smart!==false;o.mode=input.mode==='list'?'list':'grid';
o.custom=Array.isArray(input.custom)?input.custom.slice(0,1000).map(sanitizeRecipe).filter(Boolean):[];
o.custom=o.custom.filter((r,i,a)=>a.findIndex(x=>x.id===r.id)===i);
const ids=new Set([...dict.keys(),...o.custom.map(r=>r.id)]);
const validId=x=>ids.has(recipeId(x));
o.favorites=[...new Set(strArray(input.favorites).filter(validId))];o.history=[...new Set(strArray(input.history,300).filter(validId))];
for(const [k,v] of Object.entries(isObj(input.notes)?input.notes:{}))if(validId(k)&&typeof v==='string')o.notes[k]=v.slice(0,4000);
for(const [k,v] of Object.entries(isObj(input.ratings)?input.ratings:{}))if(validId(k)&&Number.isFinite(+v))o.ratings[k]=clamp(v,1,5);
for(const [k,v] of Object.entries(isObj(input.cooked)?input.cooked:{}))if(validId(k)&&typeof v==='number')o.cooked[k]=clamp(v,0,999);
for(const [k,v] of Object.entries(isObj(input.scores)?input.scores:{}))if(/^(p:|c:)/.test(k)&&Number.isFinite(+v))o.scores[k]=clamp(v,-10,10);
for(const [k,v] of Object.entries(isObj(input.savedSides)?input.savedSides:{}))if(validId(k)&&hasOwn(sides,v))o.savedSides[k]=v;
o.collections=(Array.isArray(input.collections)?input.collections:[]).filter(c=>isObj(c)&&asText(c.name,80).trim()).slice(0,200).map((c,i)=>({id:'col:'+i,name:asText(c.name,80),ids:[...new Set(strArray(c.ids).filter(validId))]}));
o.pantryItems=normalizePantry(input.pantryItems,input.pantry);o.pantry=activePantry(o.pantryItems);o.exclude=[...new Set(strArray(input.exclude,100).map(x=>x.trim()).filter(Boolean))];
o.shop=(Array.isArray(input.shop)?input.shop:[]).slice(0,2000).filter(i=>isObj(i)&&asText(i.name,100).trim()).map(i=>({name:asText(i.name,100),qty:clamp(i.qty,0.01,100000),unit:asText(i.unit,20),done:!!i.done}));
for(const [k,v] of Object.entries(isObj(input.plan)?input.plan:{}))if(/^\d{4}-\d{2}-\d{2}$/.test(k)&&Array.isArray(v)){o.plan[k]=v.slice(0,12).filter(d=>isObj(d)&&validId(d.id)).map(d=>({id:recipeId(d.id),people:clamp(d.people,1,24),side:hasOwn(sides,d.side)?d.side:null,meal:['Reggeli','Ebéd','Vacsora','Egyéb'].includes(d.meal)?d.meal:'Ebéd'}));}
return o}
function parseLocal(k,f){try{return JSON.parse(localStorage.getItem(k))??f}catch{return f}}
function migrateV1(){const o=baseDefaults();o.people=clamp(parseLocal('mit_people',2),1,24);if(parseLocal('mit_dark',false))o.theme='dark';o.favorites=strArray(parseLocal('mit_fav',[]));o.shop=parseLocal('mit_shop',[]);const wk=parseLocal('mit_week',[]);if(Array.isArray(wk)){const d=new Date();d.setDate(d.getDate()-(d.getDay()+6)%7);for(let i=0;i<7;i++){const x=wk[i];if(x)o.plan[dateKey(d)]=[{id:recipeId(x.id),people:x.people,side:x.side,meal:'Ebéd'}];d.setDate(d.getDate()+1)}}return o}
let data;
try{data=sanitizeData(parseLocal('mit_v2',null)||migrateV1())}catch{data=baseDefaults()}
let S={tab:'home',query:'',filter:{protein:'',cuisine:'',side:'',time:'',type:'',method:'',origin:'',spicy:'',difficulty:'',holiday:'',baking:false,bakeTaste:'',bakeKind:'',bakeFlavor:'',pantry:false},sort:'recommended',limit:24,result:null,detail:null,modal:null,week:0,favMode:'all',collection:null,timerEnd:0,timerLeft:0,seen:[],scroll:0};
let all=[],byId=new Map(),searchIndex=new Map(),ingIndex=new Map();
// A költséges keresőindex csak tényleges kereséskor épül fel.
function rebuild(){all=[...recipes,...data.custom];byId=new Map(all.map(r=>[String(r.id),r]));searchIndex=new Map();ingIndex=new Map()}
function indexFor(r){if(!searchIndex.has(r.id))searchIndex.set(r.id,norm([r.name,r.cuisine,r.protein,r.type,r.method,r.side,r.bakery?.taste,r.bakery?.kind,r.bakery?.flavor,...r.ing.map(i=>i.name)].join(' ')));return searchIndex.get(r.id)}
function ingredientsFor(r){if(!ingIndex.has(r.id))ingIndex.set(r.id,r.ing.map(i=>norm(i.name)));return ingIndex.get(r.id)}
rebuild();
let storageWarning=false;
function persist(){refreshPantry();try{localStorage.setItem('mit_v2',JSON.stringify(data));storageWarning=false;return true}catch{storageWarning=true;notify('A tároló megtelt vagy nem érhető el. Készíts biztonsági mentést!');return false}}
function notify(text){$('toast').innerHTML='<div class="toast">'+esc(text)+'</div>';clearTimeout(notify.t);notify.t=setTimeout(()=>$('toast').innerHTML='',2700)}
const icons={pot:'<path d="M3 10h18l-1 9H4zM2 9h20M8 6V3m4 3V2m4 4V3M3 13H1m20 0h2"/>',home:'<path d="m3 10 9-7 9 7v10h-6v-6H9v6H3z"/>',search:'<circle cx="10.8" cy="10.8" r="6.8"/><path d="m16 16 4 4"/>',heart:'<path d="M20.8 8.5c0 5-8.8 10.5-8.8 10.5S3.2 13.5 3.2 8.5A4.8 4.8 0 0 1 12 6a4.8 4.8 0 0 1 8.8 2.5Z"/>',calendar:'<rect x="3" y="5" width="18" height="16" rx="2"/><path d="M7 3v5m10-5v5M3 11h18M7 15h2m3 0h2m3 0h2M7 18h2m3 0h2"/>',cart:'<path d="M2 3h3l2.5 12h11l3-9H7M9 15l-1 3h12"/><circle cx="10" cy="21" r="1"/><circle cx="18" cy="21" r="1"/>',settings:'<circle cx="12" cy="12" r="3"/><path d="m10 3-1 3-3 1-3 3 2 2-1 4 3 3 3-1 2 3 3-3 3 1 3-3-1-4 2-2-3-3-3-1-1-3z"/>',spark:'<path d="M12 2 9 9l-7 3 7 3 3 7 3-7 7-3-7-3z"/>',clock:'<circle cx="12" cy="12" r="9"/><path d="M12 7v5l3 2"/>',person:'<circle cx="12" cy="7" r="3"/><path d="M5 21v-3a7 7 0 0 1 14 0v3"/>',chevron:'<path d="m9 18 6-6-6-6"/>',back:'<path d="m15 18-6-6 6-6"/>',plus:'<path d="M12 5v14M5 12h14"/>',close:'<path d="m6 6 12 12M18 6 6 18"/>',check:'<path d="m5 12 5 5L20 7"/>',filter:'<path d="M4 7h16M7 12h10m-7 5h4"/><circle cx="8" cy="7" r="2" fill="currentColor"/>',shuffle:'<path d="M3 7h3l11 10h4m-4-4 4 4-4 4M3 17h3l4-4m4-4 3-2h4m-4-4 4 4-4 4"/>',folder:'<path d="M3 6h7l2 3h9v11H3z"/>',download:'<path d="M12 3v12m-5-5 5 5 5-5M3 16v5h18v-5"/>',upload:'<path d="M12 16V4m-5 5 5-5 5 5M3 16v5h18v-5"/>',share:'<path d="M12 15V3m-5 5 5-5 5 5M5 11v10h14V11"/>',trash:'<path d="M3 6h18M8 6V3h8v3M6 6l1 15h10l1-15M10 10v7m4-7v7"/>',edit:'<path d="m4 16 12-12 4 4L8 20H4zM13 7l4 4"/>',grid:'<rect x="3" y="3" width="7" height="7" rx="1"/><rect x="14" y="3" width="7" height="7" rx="1"/><rect x="3" y="14" width="7" height="7" rx="1"/><rect x="14" y="14" width="7" height="7" rx="1"/>',list:'<path d="M8 5h13M8 12h13M8 19h13M3 5h1m-1 7h1m-1 7h1"/>',box:'<path d="m3 7 9-4 9 4v14H3zM3 7l9 4 9-4m-9 4v10"/>',book:'<path d="M3 4h8l1 2 1-2h8v16h-8l-1 1-1-1H3zM12 6v15"/>',moon:'<path d="M20 14A9 9 0 0 1 10 3a9 9 0 1 0 10 11z"/>',sun:'<circle cx="12" cy="12" r="4"/><path d="M12 2v3m0 14v3M2 12h3m14 0h3M5 5l2 2m10 10 2 2M5 19l2-2M17 7l2-2"/>',star:'<path d="m12 3 2.8 5.7 6.2.9-4.5 4.4 1.1 6.2-5.6-3-5.6 3 1.1-6.2L3 9.6l6.2-.9Z"/>'};
const ic=name=>'<svg class="ico" viewBox="0 0 24 24" aria-hidden="true">'+(icons[name]||icons.pot)+'</svg>';
const btn=(label,action,cls='primary',icon='')=>'<button class="btn '+cls+'" onclick="'+action+'">'+(icon?ic(icon):'')+esc(label)+'</button>';
const ib=(label,action,icon)=>'<button class="iconbtn" aria-label="'+esc(label)+'" title="'+esc(label)+'" onclick="'+action+'">'+ic(icon)+'</button>';
const title=(name,sub='')=>'<div class="page-title"><h1>'+esc(name)+'</h1>'+(sub?'<p>'+esc(sub)+'</p>':'')+'</div>';
const sec=(name,action='')=>'<div class="section-title"><h2>'+esc(name)+'</h2>'+action+'</div>';
const empty=(msg,icon='pot')=>'<div class="empty">'+ic(icon)+esc(msg)+'</div>';
const tag=(txt,extra='')=>'<span class="tag '+extra+'">'+esc(txt)+'</span>';
const opts=(items,selected,all=null)=> (all!==null?'<option value="">'+esc(all)+'</option>':'')+items.map(x=>'<option '+(String(x)===String(selected)?'selected':'')+' value="'+esc(x)+'">'+esc(x)+'</option>').join('');
function selectField(label,items,selected,handler,all=null){return '<label class="field">'+esc(label)+'<select onchange="'+handler+'">'+opts(items,selected,all)+'</select></label>'}
const peopleOpts=(n,bake=false)=>Array.from({length:24},(_,i)=>'<option value="'+(i+1)+'" '+(i+1===+n?'selected':'')+'>'+(i+1)+(bake?' adag':' fő')+'</option>').join('');
function sideOpts(n){return opts(Object.keys(sides),n)}
function art(r){if(r.type==='Leves')return 'soup';if(r.type==='Desszert')return 'dessert';if(r.type==='Reggeli')return 'breakfast';if(/tészta|spagetti|carbonara/i.test(r.name))return 'pasta';return ({Csirke:'poultry',Pulyka:'poultry',Kacsa:'poultry',Sertés:'pork',Marha:'beef',Bárány:'beef',Hal:'fish','Tenger gyümölcsei':'seafood',Húsmentes:'plant'})[r.protein]||'mixed'}
function photoFor(r){const n=norm(r.name);if(r.bakery){if(n.includes('bejgli'))return 'beigli';return bakeryPhoto(r.bakery)}if(n.includes('bejgli'))return 'beigli';if(n.includes('paprikas csirke')||n.includes('csirkepaprikas'))return 'paprikas';if(n.includes('husveti sonka'))return 'easter';if(r.type==='Saláta'||n.includes('salata'))return 'salad';if(r.protein==='Kacsa'&&r.holidays?.length)return 'holiday';if(r.method==='Forrólevegős sütő'&&['Csirke','Pulyka'].includes(r.protein))return 'airfryer';const a=art(r);return a==='mixed'?'plant':a}
const img=(r,cls='')=>'<img class="'+cls+'" src="photos/'+photoFor(r)+'.jpg" alt="Ételkategória illusztrációja" loading="lazy">';
const keyArg=x=>"'"+String(x).replace(/[^a-zA-Z0-9:_-]/g,'')+"'";
function rId(r){return keyArg(r.id)}
function tile(r){const id=rId(r),saved=data.favorites.includes(r.id);return '<article class="tile"><button class="tile-open" onclick="openRecipe('+id+')"><div class="tile-art">'+img(r)+'<span class="art-label">'+esc(r.cuisine)+'</span></div><div class="tile-content"><h3>'+esc(r.name)+'</h3><div class="meta">'+ic('clock')+r.time+' perc · '+esc(r.protein)+'</div><div class="row wrap" style="margin-top:7px">'+tag(r.origin==='variáció'?'Variáció':r.origin==='saját'?'Saját':'Klasszikus')+tag(r.difficulty||'Közepes')+(r.bakery?tag(r.bakery.taste,'gold'):'')+(r.holidays?.length?tag(r.holidays[0],'gold'):'')+(r.spicy?tag('Csípős','gold'):'')+'</div></div></button><button class="heart '+(saved?'saved':'')+'" onclick="favorite('+id+')" aria-label="'+(saved?'Kedvenc törlése':'Mentés kedvencekbe')+'">'+ic('heart')+'</button></article>'}
function listCard(r){return '<div class="list-card"><button class="row grow" style="padding:0;text-align:left" onclick="openRecipe('+rId(r)+')">'+img(r,'thumb')+'<div class="grow"><h3>'+esc(r.name)+'</h3><div class="meta">'+r.time+' perc · '+esc(r.cuisine)+' · '+esc(r.protein)+'</div></div></button>'+ib('Kedvenc', 'favorite('+rId(r)+')','heart')+'</div>'}
const drawList=(arr,forceGrid=false)=>'<div class="'+(forceGrid||data.mode==='grid'?'grid':'stack')+'">'+arr.map(forceGrid||data.mode==='grid'?tile:listCard).join('')+'</div>';
function filtered(ignoreQuery=false){const f=S.filter,q=ignoreQuery?'':norm(S.query),words=q?q.split(/\s+/):[],excluded=data.exclude.map(norm);return all.filter(r=>{
if(f.baking&&!r.bakery||f.bakeTaste&&r.bakery?.taste!==f.bakeTaste||f.bakeKind&&r.bakery?.kind!==f.bakeKind||f.bakeFlavor&&r.bakery?.flavor!==f.bakeFlavor||f.difficulty&&r.difficulty!==f.difficulty||f.holiday&&!r.holidays?.includes(f.holiday)||f.protein&&r.protein!==f.protein||f.cuisine&&r.cuisine!==f.cuisine||f.side&&r.side!==f.side||f.time&&r.time>+f.time||f.type&&(f.type==='Sütemény'?!r.bakery&&r.type!==f.type:r.type!==f.type)||f.method&&r.method!==f.method||f.origin&&r.origin!==f.origin||f.spicy==='yes'&&!r.spicy||f.spicy==='no'&&r.spicy)return false;
if(excluded.length&&excluded.some(x=>ingredientsFor(r).some(n=>n.includes(x))))return false;
if(f.pantry&&pantryScore(r)<.45)return false;
return !words.length||words.every(x=>indexFor(r).includes(x));})}
function pantryScore(r){if(!data.pantry.length)return 0;const have=data.pantry.map(norm);const list=r.ing.filter(i=>!['só','víz','étolaj','semleges étolaj','olaj','bors'].includes(i.name));return list.length?list.filter(i=>have.some(h=>norm(i.name).includes(h)||h.includes(norm(i.name)))).length/list.length:0}
function smartWeight(r){return Math.max(.1,2+(data.scores['p:'+r.protein]||0)*.17+(data.scores['c:'+r.cuisine]||0)*.21+(data.favorites.includes(r.id)?2:0)+(data.ratings[r.id]||0)*.18+(r.origin==='klasszikus'?2:0)+pantryScore(r)*2-(data.history.indexOf(r.id)>=0?.5:0))}
function choose(pool){if(!pool.length)return null;const fresh=pool.filter(r=>!S.seen.includes(r.id));const list=fresh.length?fresh:pool;if(!data.smart)return list[Math.floor(Math.random()*list.length)];const ws=list.map(smartWeight);let v=Math.random()*ws.reduce((a,b)=>a+b,0);return list.find((r,i)=>(v-=ws[i])<=0)||list[list.length-1]}
function filterCount(){return Object.values(S.filter).filter(Boolean).length}
function setFilter(k,v){if(!hasOwn(S.filter,k))return;S.filter[k]=v;if(['bakeTaste','bakeKind','bakeFlavor'].includes(k)&&v)S.filter.baking=true;S.limit=24;S.result=null;renderMain();if(S.modal==='filters')showFilters()}
function resetFilters(){Object.keys(S.filter).forEach(k=>S.filter[k]=k==='pantry'||k==='baking'?false:'');S.query='';S.limit=24;S.result=null;renderMain();if(S.modal==='filters')showFilters()}
function pickCuisine(c){S.filter.cuisine=c;S.filter.origin='';S.query='';S.limit=24;go('browse')}
function quickCollection(n){resetFilters();if(n===1){S.filter.method='Forrólevegős sütő';go('browse')}else if(n===2){go('browse');showHolidayPicker()}}
function pickQuick(k,v){S.filter[k]=v;S.query='';S.limit=24;go('browse')}
const navItems=[['home','home','Főoldal'],['browse','search','Receptek'],['saved','heart','Mentések'],['plan','calendar','Menü'],['shop','cart','Lista']];
function go(t){document.body.style.overflow='';S.tab=t;S.detail=null;S.modal=null;$('overlays').innerHTML='';render();window.scrollTo(0,0)}
function theme(){const dark=data.theme==='dark'||data.theme==='auto'&&window.matchMedia&&matchMedia('(prefers-color-scheme: dark)').matches;document.body.classList.toggle('dark',dark);try{window.AndroidShare?.setDark(dark)}catch{}}
function render(){theme();$('header').innerHTML='<div class="brand"><span class="logo-icon">'+ic('pot')+'</span>Mit főzzek?</div><div class="header-tools">'+ib('Kamra','showPantry()','box')+ib('Beállítások','showSettings()','settings')+'</div>';$('nav').className='nav';$('nav').innerHTML=navItems.map(([id,i,n])=>'<button class="'+(S.tab===id?'active':'')+'" onclick="go(\''+id+'\')">'+ic(i)+esc(n)+'</button>').join('');renderMain()}
function renderMain(){refreshPantry();const views={home,browse,saved,plan,shop};$('main').innerHTML=(views[S.tab]||home)();if(S.tab==='browse')updateResults()}
function home(){const day=new Date().toLocaleDateString('hu-HU',{month:'long',day:'numeric',weekday:'long'});const r=S.result?byId.get(S.result):null;const picks=recipes.filter(x=>x.origin==='klasszikus'&&x.time<=35).filter((x,i)=>i%3===0).slice(0,6);return '<div class="row between small muted" style="margin:6px 2px 12px"><span>'+esc(day)+'</span><span>'+ic('person')+' '+data.people+' fő</span></div><section class="hero"><div class="upper">Fedezd fel a világ konyháit</div><h1>Mi legyen ma<br>az ebéd?</h1><p>Találj új kedvenceket, tervezz előre, főzz abból, amid van.</p><button class="hero-button" onclick="roll()">'+ic('spark')+' Sorsolj egy ételt!</button><img src="photos/poultry.jpg" alt=""></section><div class="stat-grid"><div class="stat"><b>'+all.length.toLocaleString('hu-HU')+'</b><span>receptötlet</span></div><div class="stat"><b>'+cuisines.length+'</b><span>konyha</span></div><div class="stat"><b>'+data.favorites.length+'</b><span>kedvenc</span></div></div><section class="section"><button class="bakery-banner" onclick="openBakery()"><div><span class="upper">Új receptválogatás</span><b>Sütemények</b><small>Édes és sós finomságok</small></div><img src="photos/bake-pogacsa.jpg" alt=""></button></section><section class="section">'+sec('Mit kívánsz?', '<button class="link" onclick="showFilters()">Részletes szűrés '+(filterCount()?'('+filterCount()+')':'')+'</button>')+'<div class="card fields">'+selectField('Húsfajta',proteins,S.filter.protein,"setFilter(\'protein\',this.value)",'Mindegy')+selectField('Konyha',cuisines,S.filter.cuisine,"setFilter(\'cuisine\',this.value)",'Mindegy')+selectField('Köret',Object.keys(sides),S.filter.side,"setFilter(\'side\',this.value)",'Mindegy')+'<label class="field">Adag<select onchange="setPeople(this.value)">'+peopleOpts(data.people)+'</select></label><label class="field full">Sorsolás<select onchange="data.smart=this.value===\'yes\';persist()"><option value="yes" '+(data.smart?'selected':'')+'>Ízlésem alapján</option><option value="no" '+(!data.smart?'selected':'')+'>Teljesen véletlen</option></select></label><div class="full row between"><span class="small muted">'+filtered(true).length+' találat</span><button class="link" onclick="resetFilters()">Szűrők törlése</button></div></div><div class="spacer"></div>'+btn('Lepj meg!','roll()','primary block','shuffle')+'</section>'+(r?resultCard(r):'')+'<section class="section">'+sec('Különleges válogatások')+'<div class="feature-grid"><button class="feature-card" onclick="quickCollection(1)"><img src="photos/airfryer.jpg" alt=""><b>Forrólevegős sütő</b><span>Ropogós ötletek</span></button><button class="feature-card" onclick="quickCollection(2)"><img src="photos/holiday.jpg" alt=""><b>Ünnepi receptek</b><span>Alkalomra válogatva</span></button></div></section>'+'<section class="section">'+sec('Gyors ötletek','<button class="link" onclick="pickQuick(\'time\',\'30\')">30 perc alatt ›</button>')+drawList(picks,true)+'<p class="small muted">Az ételképek illusztrációk.</p></section><section class="section">'+sec('Válassz konyhát')+'<div class="chip-list">'+cuisines.map(c=>'<button class="chip" data-cuisine="'+esc(c)+'" onclick="pickCuisine(this.dataset.cuisine)">'+esc(c)+'</button>').join('')+'</div></section>'}
function resultCard(r){return '<section id="result" class="result"><div class="result-art">'+img(r)+'<span class="art-label"></span></div><div class="result-body"><div class="row between"><span class="upper">A mai ajánlatunk</span>'+tag(r.origin==='variáció'?'Receptvariáció':'Recept')+'</div><h2>'+esc(r.name)+'</h2><div class="meta-row">'+ic('clock')+r.time+' perc · '+esc(r.cuisine)+' · '+esc(r.side)+'</div><div class="spacer"></div><div class="row">'+btn('Másikat kérek','skip()','secondary grow','shuffle')+btn('Megnézem','openRecipe('+rId(r)+')','primary grow','chevron')+'</div></div></section>'}
function roll(){const pool=filtered(true),r=choose(pool);if(!r){notify('Nincs megfelelő recept. Lazíts a szűrőkön!');return}S.result=r.id;S.seen.push(r.id);S.seen=S.seen.slice(-40);if(S.tab!=='home')go('home');else renderMain();setTimeout(()=>{const el=$('result');if(el)el.scrollIntoView({behavior:'smooth',block:'start'})},80)}
function learn(r,delta){for(const [prefix,value] of [['p:',r.protein],['c:',r.cuisine]])data.scores[prefix+value]=clamp((data.scores[prefix+value]||0)+delta,-10,10)}
function skip(){const r=byId.get(S.result);if(r){learn(r,-.3);persist()}roll()}
function setPeople(n){data.people=clamp(n,1,24);persist();renderMain()}
function browse(){return title(S.filter.baking?'Sütemények':'Receptkönyv',S.filter.baking?'Édes és sós házi finomságok, szűrhető válogatás.':'Keresés több ezer magyar nyelvű fogás között. A képek ételtípus-illusztrációk.')+'<div class="searchbox">'+ic('search')+'<input id="search" placeholder="Étel, hozzávaló, konyha..." value="'+esc(S.query)+'" oninput="queryChanged(this.value)" aria-label="Receptek keresése">'+ib('Szűrés','showFilters()','filter')+'</div>'+bakeryBar()+'<div class="section chip-list">'+[['','Minden'],['klasszikus','Klasszikusok'],['variáció','Variációk'],['saját','Saját receptek']].map(([v,n])=>'<button class="chip '+(S.filter.origin===v?'on':'')+'" onclick="setFilter(\'origin\',\''+v+'\')">'+n+'</button>').join('')+'</div><div class="row between section"><div id="count" class="small muted grow"></div><button class="chip" onclick="showFilters()">'+ic('filter')+' Szűrők '+(filterCount()?'('+filterCount()+')':'')+'</button>'+ib('Nézet váltása','toggleMode()',data.mode==='grid'?'list':'grid')+'</div><div class="row between" style="margin:9px 0"><label class="field grow">Rendezés<select onchange="S.sort=this.value;S.limit=24;updateResults()"><option value="recommended" '+(S.sort==='recommended'?'selected':'')+'>Ajánlott</option><option value="time" '+(S.sort==='time'?'selected':'')+'>Leggyorsabb</option><option value="name" '+(S.sort==='name'?'selected':'')+'>Név szerint</option><option value="pantry" '+(S.sort==='pantry'?'selected':'')+'>Kamrában lévők szerint</option><option value="rating" '+(S.sort==='rating'?'selected':'')+'>Saját értékelés</option></select></label>'+btn('Saját recept','editRecipe()','secondary','plus')+'</div><div id="results"></div>'}
function queryChanged(q){S.query=q;S.limit=24;clearTimeout(queryChanged.t);queryChanged.t=setTimeout(updateResults,90)}
function updateResults(){if(!$('results'))return;const list=filtered();if(S.sort==='time')list.sort((a,b)=>a.time-b.time);else if(S.sort==='name')list.sort((a,b)=>a.name.localeCompare(b.name,'hu'));else if(S.sort==='pantry'){const scores=new Map(list.map(r=>[r.id,pantryScore(r)]));list.sort((a,b)=>scores.get(b.id)-scores.get(a.id))}else if(S.sort==='rating')list.sort((a,b)=>(data.ratings[b.id]||0)-(data.ratings[a.id]||0));else {const weights=new Map(list.map(r=>[r.id,smartWeight(r)]));list.sort((a,b)=>weights.get(b.id)-weights.get(a.id))};$('count').textContent=list.length.toLocaleString('hu-HU')+' találat';$('results').innerHTML=list.length?drawList(list.slice(0,S.limit))+(list.length>S.limit?'<div class="section">'+btn('További receptek ('+Math.min(24,list.length-S.limit)+')','S.limit+=24;updateResults()','secondary block')+'</div>':''):empty('Nincs találat. Próbálj más keresést vagy szűrést.','search')}
function toggleMode(){data.mode=data.mode==='grid'?'list':'grid';persist();renderMain()}
function modal(html,key='generic'){S.modal=key;const old=$('modal');if(old)old.remove();const div=document.createElement('div');div.id='modal';div.className='modal-cover';div.innerHTML='<div class="modal" role="dialog" aria-modal="true">'+html+'</div>';div.addEventListener('click',e=>{if(e.target===div)closeModal()});$('overlays').appendChild(div)}
function modalHead(name){return '<div class="row between"><h2>'+esc(name)+'</h2>'+ib('Bezárás','closeModal()','close')+'</div>'}
function closeModal(){const el=$('modal');if(el)el.remove();S.modal=null}
function showFilters(){const f=S.filter;modal(modalHead('Szűrők')+'<div class="fields">'+selectField('Húsfajta',proteins,f.protein,"setFilter(\'protein\',this.value)",'Mindegy')+selectField('Konyha',cuisines,f.cuisine,"setFilter(\'cuisine\',this.value)",'Mindegy')+selectField('Köret',Object.keys(sides),f.side,"setFilter(\'side\',this.value)",'Mindegy')+selectField('Maximális idő',[15,20,30,45,60,90,120,180,240,360],f.time,"setFilter(\'time\',this.value)",'Bármennyi')+selectField('Fogás típusa',types,f.type,"setFilter(\'type\',this.value)",'Mindegy')+selectField('Elkészítés',methods,f.method,"setFilter(\'method\',this.value)",'Mindegy')+selectField('Nehézségi szint',difficulties,f.difficulty,"setFilter('difficulty',this.value)",'Mindegy')+selectField('Ünnep',holidays,f.holiday,"setFilter('holiday',this.value)",'Mindegy')+selectField('Recepttípus',['klasszikus','variáció','saját'],f.origin,"setFilter(\'origin\',this.value)",'Mindegy')+bakeryFilterFields()+'<label class="field">Csípősség<select onchange="setFilter(\'spicy\',this.value)"><option value="">Mindegy</option><option value="yes" '+(f.spicy==='yes'?'selected':'')+'>Csípős</option><option value="no" '+(f.spicy==='no'?'selected':'')+'>Nem csípős</option></select></label><label class="field full"><span class="row"><input type="checkbox" '+(f.pantry?'checked':'')+' onchange="setFilter(\'pantry\',this.checked)">Csak a kamrámhoz illő receptek</span></label></div><div class="notice" style="margin-top:12px">A kizárt hozzávalók a Beállításokban adhatók meg. A szöveges kizárás nem garantál allergénmentességet.</div><div class="row">'+btn('Alaphelyzet','resetFilters()','secondary grow')+btn(filtered().length+' találat','closeModal()','primary grow')+'</div>','filters')}
function favorite(id){const r=byId.get(id);if(!r)return;const n=data.favorites.indexOf(id);if(n<0){data.favorites.push(id);learn(r,1)}else{data.favorites.splice(n,1);learn(r,-1)}persist();renderMain();if(S.detail)renderDetail(true);notify(n<0?'Kedvencekhez adva':'Kedvenc törölve')}
function chosenIngredients(r,side,people){let base=r.ing.slice(),factor=people/r.base,result;const replacement=side!==r.side&&r.swap;
if(replacement&&!r.separate)base=r.swapIng||base;
result=base.map(i=>({...i,qty:i.qty*factor}));
if(r.separate||replacement){for(const [name,q,u] of (sides[side]?.ing||[]))result.push({name,qty:q*people/2,unit:u})}
return mergeItems(result)}
function mergeItems(arr){const map=new Map();for(const x of arr){let n=x.name,u=x.unit,q=+x.qty;if(u==='kg'){u='g';q*=1000}if(u==='l'){u='ml';q*=1000}const key=norm(n)+'|'+u;const old=map.get(key);map.set(key,{name:old?.name||n,unit:u,qty:(old?.qty||0)+q})}return [...map.values()]}
function scaleStep(text,factor){if(factor===1)return text;return text.replace(/(\d+(?:[.,]\d+)?)(?:\s*[–-]\s*(\d+(?:[.,]\d+)?))?\s*(kg|g|dl|ml|l|ek|tk|evőkanál|teáskanál)(?=\s|[.,;:!?) -]|$)/giu,(m,a,b,u)=>qty(Number(a.replace(',','.'))*factor)+(b?'–'+qty(Number(b.replace(',','.'))*factor):'')+' '+u)}
function chosenSteps(r,side,people=r.base){const replacement=side!==r.side&&r.swap;let steps=replacement&&!r.separate?r.swapSteps||r.steps:r.steps;const prep=(r.separate||replacement)&&sides[side]?.steps?[sides[side].steps]:[];return [...prep.map(x=>scaleStep(x,people/2)),...steps.map(x=>scaleStep(x,people/r.base))]}
function openRecipe(id,side=null,people=null){const r=byId.get(id);if(!r)return;S.detail={id,side:r.swap&&(side&&hasOwn(sides,side)||data.savedSides[id]&&hasOwn(sides,data.savedSides[id]))?(side||data.savedSides[id]):r.side,people:people||(r.bakery?r.base:data.people),checked:[],steps:[],cooking:false};data.history=[id,...data.history.filter(x=>x!==id)].slice(0,300);persist();renderDetail()}
function detailChange(k,v){const d=S.detail;if(!d)return;if(k==='people')d.people=clamp(v,1,24);if(k==='side'&&byId.get(d.id).swap&&hasOwn(sides,v)){d.side=v;data.savedSides[d.id]=v;persist()}d.checked=[];d.steps=[];renderDetail(true)}
function renderDetail(keep=false){const d=S.detail,r=d&&byId.get(d.id);if(!r)return;const prev=$('detail'),scroll=keep&&prev?prev.scrollTop:0;if(prev)prev.remove();const ing=chosenIngredients(r,d.side,d.people),steps=chosenSteps(r,d.side,d.people),score=data.ratings[r.id]||0,el=document.createElement('section');el.id='detail';el.className='sheet';
el.innerHTML='<div class="sheet-inner"><div class="sheet-top">'+btn('Vissza','closeDetail()','secondary','back')+'<div class="row">'+ib('Gyűjteményhez adás','collectionPicker()','folder')+ib('Recept megosztása','shareRecipe()','share')+'<button class="iconbtn" style="color:'+(data.favorites.includes(r.id)?'#c34b40':'var(--text)')+'" onclick="favorite('+rId(r)+')" aria-label="Kedvenc">'+ic('heart')+'</button></div></div><div class="detail-art">'+img(r)+'<span class="tag">'+esc(r.cuisine)+' · '+esc(r.origin==='variáció'?'Saját receptvariáció':r.origin==='saját'?'Saját recept':'Klasszikus recept')+'</span></div><h1 class="detail-name">'+esc(r.name)+'</h1><div class="meta-row">'+ic('clock')+' '+r.time+' perc · '+esc(r.protein)+' · '+esc(r.method)+'</div><div class="row section wrap">'+tag(r.type)+tag(r.difficulty||'Közepes')+(r.bakery?tag(r.bakery.taste,'gold')+tag(r.bakery.kind)+tag(r.bakery.flavor):'')+(r.holidays||[]).map(x=>tag(x,'gold')).join('')+(r.spicy?tag('Csípős','gold'):'')+(r.swap?tag('Cserélhető köret'):'')+'</div><div class="card fields section"><label class="field">Adagszám<select onchange="detailChange(\'people\',this.value)">'+peopleOpts(d.people,!!r.bakery)+'</select></label><label class="field">Köret'+(r.swap?'<select onchange="detailChange(\'side\',this.value)">'+sideOpts(d.side)+'</select>':'<span class="notice">'+esc(r.side)+' (az étel része)</span>')+'</label></div><p class="small muted">A hozzávalók mennyisége az adagszámmal változik. A sütési hőmérséklet és idő nem szorzódik; a forma méretét igazítsd az adaghoz, szükség esetén több menetben süss.</p>'+applianceCard(r)+'<p class="small muted">MI által készített ételkategória-illusztráció, nem a konkrét fogás fényképe.</p>'+(r.origin==='variáció'?'<p class="notice section">Saját összeállítás külön hozzávalókkal és elkészítéssel. Az illusztráció kategóriaképet mutat, nem a kész fogás fényképét.</p>':'')+(d.side!==r.side&&r.separate&&r.origin==='klasszikus'?'<p class="notice section">Az eredeti köret helyett a választott köretet készítsd el. A főétel esetleges köretre utaló részét ennek megfelelően módosítsd.</p>':'')+'<section class="section">'+sec('Hozzávalók',tag(d.people+(r.bakery?' adagra':' főre')))+'<div class="card">'+ing.map((i,k)=>'<div class="ingredient"><label class="'+(d.checked.includes(k)?'checked':'')+'"><input type="checkbox" '+(d.checked.includes(k)?'checked':'')+' onchange="toggleIng('+k+',this.checked)"><span>'+esc(i.name)+'</span></label><b>'+qty(i.qty)+' '+esc(i.unit)+'</b></div>').join('')+'</div><div class="spacer"></div>'+btn('Bevásárlólistára','addRecipeShop()','primary block','cart')+'</section><section class="section">'+sec('Elkészítés','<button class="link" onclick="toggleCooking()">'+(d.cooking?'Normál nézet':'Főző mód')+'</button>')+'<div class="progress"><i style="width:'+Math.round(d.steps.length/steps.length*100)+'%"></i></div><div class="card section">'+steps.map((v,i)=>'<div class="step '+(d.steps.includes(i)?'checked':'')+'"><button class="step-number" aria-label="Lépés kipipálása" onclick="toggleStep('+i+')">'+(d.steps.includes(i)?ic('check'):i+1)+'</button><p style="'+(d.cooking?'font-size:18px':'')+'">'+esc(v)+'</p></div>').join('')+'</div><div class="row section">'+btn('Időzítő','showTimer()','secondary grow','clock')+btn('Elkészítettem','markCooked()','primary grow','check')+'</div></section><section class="section">'+sec('Saját értékelés')+'<div class="card"><div class="rating">'+[1,2,3,4,5].map(n=>'<button aria-label="'+n+' csillag" onclick="rate('+n+')">'+(n<=score?'★':'☆')+'</button>').join('')+'</div><label class="field">Saját jegyzet<textarea id="note" oninput="noteChanged(this.value)" placeholder="Mit módosítanál legközelebb?">'+esc(data.notes[r.id]||'')+'</textarea></label></div></section><div class="section">'+btn('Menübe mentés','planPicker()','primary block','calendar')+'</div>'+(r.origin==='saját'?'<div class="row section">'+btn('Szerkesztés','editRecipe('+rId(r)+')','secondary grow','edit')+btn('Törlés','deleteOwn('+rId(r)+')','outline danger grow','trash')+'</div>':'')+'<p class="muted small section">A mennyiségek és idők tájékoztató jellegűek. Az összetett termékek címkéjét ellenőrizd. Az ételt a megfelelő állagig és biztonságos belső hőmérsékletig készítsd.</p></div>';
$('overlays').insertBefore(el,$('modal'));el.scrollTop=scroll;document.body.style.overflow='hidden'}
function closeDetail(){S.detail=null;const el=$('detail');if(el)el.remove();closeModal();document.body.style.overflow='';renderMain()}
function toggleIng(k,on){const d=S.detail;if(on&&!d.checked.includes(k))d.checked.push(k);else if(!on)d.checked=d.checked.filter(i=>i!==k);const el=$('detail').querySelectorAll('.ingredient label')[k];if(el)el.classList.toggle('checked',on)}
function toggleStep(i){const d=S.detail;d.steps=d.steps.includes(i)?d.steps.filter(x=>x!==i):[...d.steps,i];renderDetail(true)}
function toggleCooking(){S.detail.cooking=!S.detail.cooking;renderDetail(true)}
function rate(n){const r=byId.get(S.detail.id);data.ratings[r.id]=n;learn(r,n>=4?.5:n<=2?-.5:0);persist();renderDetail(true)}
function noteChanged(v){data.notes[S.detail.id]=v.slice(0,4000);persist()}
function markCooked(){const r=byId.get(S.detail.id);data.cooked[r.id]=(data.cooked[r.id]||0)+1;learn(r,.3);persist();notify('Elkészített receptekhez mentve!')}
function shareText(s){if(window.AndroidShare){AndroidShare.share(s);return}if(navigator.share)navigator.share({text:s}).catch(()=>{});else if(navigator.clipboard)navigator.clipboard.writeText(s).then(()=>notify('Szöveg másolva')).catch(()=>notify('A megosztás nem elérhető'));else notify('A megosztás nem elérhető')}
function shareRecipe(){const d=S.detail,r=byId.get(d.id);shareText(r.name+'\n'+d.people+' fő · '+r.time+' perc\n\nHozzávalók:\n'+chosenIngredients(r,d.side,d.people).map(i=>'• '+qty(i.qty)+' '+i.unit+' '+i.name).join('\n')+'\n\nElkészítés:\n'+chosenSteps(r,d.side,d.people).map((s,i)=>(i+1)+'. '+s).join('\n'))}
function saved(){let list=[];if(S.favMode==='all')list=data.favorites.map(id=>byId.get(id)).filter(Boolean);else if(S.favMode==='history')list=data.history.map(id=>byId.get(id)).filter(Boolean);else if(S.favMode==='cooked')list=Object.keys(data.cooked).filter(id=>data.cooked[id]>0).map(id=>byId.get(id)).filter(Boolean);else if(S.favMode==='own')list=data.custom;else if(S.favMode==='collection')list=(data.collections.find(c=>c.id===S.collection)?.ids||[]).map(id=>byId.get(id)).filter(Boolean);const options=[['all','Kedvencek'],['history','Előzmények'],['cooked','Elkészítve'],['own','Saját']];return title('Receptjeim','Mentsd el, rendszerezd és keresd vissza a kedvenceidet.')+'<div class="chip-list">'+options.map(([v,n])=>'<button class="chip '+(S.favMode===v?'on':'')+'" onclick="S.favMode=\''+v+'\';renderMain()">'+n+'</button>').join('')+'</div><section class="section">'+sec('Gyűjtemények','<button class="link" onclick="newCollection()">＋ Új</button>')+'<div class="chip-list">'+(data.collections.length?data.collections.map(c=>'<button class="chip '+(S.favMode==='collection'&&S.collection===c.id?'on':'')+'" onclick="openCollection('+keyArg(c.id)+')">'+ic('folder')+esc(c.name)+' ('+c.ids.length+')</button>').join(''):'<span class="muted small">Még nincs gyűjteményed.</span>')+'</div></section><section class="section">'+sec(S.favMode==='collection'?(data.collections.find(c=>c.id===S.collection)?.name||'Gyűjtemény'):options.find(o=>o[0]===S.favMode)?.[1]||'Mentések',S.favMode==='collection'?'<button class="link danger" onclick="removeCollection()">Törlés</button>':S.favMode==='own'?'<button class="link" onclick="editRecipe()">＋ Új recept</button>':tag(list.length+' recept'))+(list.length?drawList(list.slice(0,S.limit))+(list.length>S.limit?btn('Továbbiak','S.limit+=24;renderMain()','secondary block'):''):empty('Még nincs itt recept. Fedezz fel új ételeket!','heart'))+'</section>'}
function newCollection(){modal(modalHead('Új gyűjtemény')+'<form onsubmit="createCollection(event)"><label class="field">Név<input id="collectionName" required maxlength="60" placeholder="Pl. Gyors vacsorák"></label><button class="btn primary block" type="submit">Mentés</button></form>')}
function createCollection(e){e.preventDefault();const name=$('collectionName').value.trim();if(!name)return;const id='col:'+Date.now().toString(36);data.collections.push({id,name,ids:S.detail?[S.detail.id]:[]});persist();closeModal();renderMain();notify('Gyűjtemény létrehozva')}
function openCollection(id){S.favMode='collection';S.collection=id;S.limit=24;renderMain()}
function removeCollection(){if(confirm('Törlöd ezt a gyűjteményt? A receptek megmaradnak.')){data.collections=data.collections.filter(c=>c.id!==S.collection);S.favMode='all';persist();renderMain()}}
function collectionPicker(){modal(modalHead('Gyűjteményhez adás')+(data.collections.length?data.collections.map(c=>'<button class="btn secondary block" onclick="toggleCollection('+keyArg(c.id)+')">'+esc(c.name)+(c.ids.includes(S.detail.id)?' ✓':'')+'</button>').join(''):'<p class="muted">Hozz létre egy gyűjteményt.</p>')+btn('Új gyűjtemény','newCollection()','primary block','plus'),'collection')}
function toggleCollection(id){const c=data.collections.find(x=>x.id===id),rid=S.detail.id;if(!c)return;c.ids=c.ids.includes(rid)?c.ids.filter(x=>x!==rid):[...c.ids,rid];persist();collectionPicker()}
function weekDates(){const d=new Date();d.setHours(12,0,0,0);d.setDate(d.getDate()-(d.getDay()+6)%7+S.week*7);return Array.from({length:7},(_,i)=>{const x=new Date(d);x.setDate(x.getDate()+i);return x})}
function plan(){const dates=weekDates(),start=dates[0].toLocaleDateString('hu-HU',{month:'short',day:'numeric'}),end=dates[6].toLocaleDateString('hu-HU',{month:'short',day:'numeric'});return title('Menütervező','Tervezd meg a hét összes étkezését.')+'<div class="card row between">'+ib('Előző hét','S.week--;renderMain()','back')+'<div style="text-align:center"><b>'+esc(start)+' – '+esc(end)+'</b><div class="small muted">'+(S.week===0?'Ezen a héten':S.week>0?S.week+' hét múlva':Math.abs(S.week)+' hete')+'</div></div>'+ib('Következő hét','S.week++;renderMain()','chevron')+'</div><div class="row section">'+btn('Heti ötletek','generateWeek()','primary grow','spark')+btn('Mai hét','S.week=0;renderMain()','secondary')+'</div><div class="card section">'+dates.map((d,i)=>{const key=dateKey(d),meals=data.plan[key]||[];return '<div class="day" style="align-items:flex-start"><div class="day-date">'+dayNames[i]+'<b>'+d.getDate()+'</b></div><div class="grow stack"><div class="row between"><b>'+dayLong[i]+(key===today()?' · Ma':'')+'</b>'+ib('Étel hozzáadása','dayPicker(\''+key+'\')','plus')+'</div>'+(meals.length?meals.map((m,k)=>{const r=byId.get(m.id);return r?'<div class="row"><div class="grow"><span class="small muted">'+esc(m.meal)+' · '+m.people+' fő</span><button class="meal-title" onclick="openPlanned(\''+key+'\','+k+')">'+esc(r.name)+'</button></div>'+ib('Étel törlése','removeMeal(\''+key+'\','+k+')','trash')+'</div>':''}).join(''):'<p class="small muted">Nincs terv</p>')+'</div></div>'}).join('')+'</div><div class="section">'+btn('Heti hozzávalók a bevásárlólistára','weekShop()','primary block','cart')+'</div><div class="section">'+btn('Heti menü megosztása','shareWeek()','outline block','share')+'</div>'}
function planPicker(){modal(modalHead('Menübe mentés')+'<form onsubmit="commitPlan(event)"><div class="fields"><label class="field full">Dátum<input id="planDate" type="date" value="'+today()+'" required></label><label class="field full">Étkezés<select id="planMeal">'+opts(['Reggeli','Ebéd','Vacsora','Egyéb'],'Ebéd')+'</select></label></div><button type="submit" class="btn primary block">Hozzáadás a menühöz</button></form>','plan')}
function commitPlan(e){e.preventDefault();const d=S.detail,date=$('planDate').value,meal=$('planMeal').value;if(!d||!/^\d{4}-\d{2}-\d{2}$/.test(date))return;data.plan[date]=[...(data.plan[date]||[]),{id:d.id,side:d.side,people:d.people,meal}].slice(0,12);persist();closeModal();notify('Étel menübe mentve')}
function dayPicker(key){modal(modalHead('Étel hozzáadása')+'<div class="searchbox">'+ic('search')+'<input id="daySearch" placeholder="Keresés receptek között" oninput="daySearch(\''+key+'\',this.value)"></div><label class="field" style="margin-top:10px">Étkezés<select id="dayMeal">'+opts(['Reggeli','Ebéd','Vacsora','Egyéb'],'Ebéd')+'</select></label><div id="dayResults" class="stack section"></div>','day');daySearch(key,'')}
function daySearch(key,q){const pool=q.trim()?all.filter(r=>indexFor(r).includes(norm(q))).slice(0,20):[...data.favorites.map(id=>byId.get(id)).filter(Boolean),...recipes.filter(r=>r.origin==='klasszikus').slice(0,10)].slice(0,12);$('dayResults').innerHTML=pool.length?pool.map(r=>'<button class="list-card" onclick="addDay(\''+key+'\','+rId(r)+')">'+img(r,'thumb')+'<div class="grow"><h3>'+esc(r.name)+'</h3><span class="small muted">'+r.time+' perc</span></div>'+ic('plus')+'</button>').join(''):empty('Nincs találat.','search')}
function addDay(key,id){const r=byId.get(id);if(!r)return;data.plan[key]=[...(data.plan[key]||[]),{id,people:data.people,side:r.side,meal:$('dayMeal').value}].slice(0,12);persist();closeModal();renderMain()}
function openPlanned(date,k){const m=data.plan[date]?.[k];if(m)openRecipe(m.id,m.side,m.people)}
function removeMeal(date,k){data.plan[date].splice(k,1);persist();renderMain()}
function generateWeek(){const pool=filtered(true);if(!pool.length){notify('Nincs a szűrőknek megfelelő recept.');return}const used=new Set();for(const d of weekDates()){const key=dateKey(d);if(data.plan[key]?.some(m=>m.meal==='Ebéd'))continue;let p=pool.filter(r=>!used.has(r.id)&&r.type==='Főétel');if(!p.length)p=pool;const r=choose(p);used.add(r.id);data.plan[key]=[...(data.plan[key]||[]),{id:r.id,side:r.side,people:data.people,meal:'Ebéd'}]}persist();renderMain();notify('A hiányzó ebédeket kitöltöttem')}
function currentMeals(){return weekDates().flatMap(d=>data.plan[dateKey(d)]||[])}
function weekShop(){const arr=currentMeals().flatMap(m=>{const r=byId.get(m.id);return r?chosenIngredients(r,m.side||r.side,m.people):[]});if(!arr.length){notify('A heti menü üres.');return}addItems(arr);go('shop');notify('Heti hozzávalók hozzáadva')}
function shareWeek(){shareText('Heti menü\n'+weekDates().map((d,i)=>dayLong[i]+' '+d.toLocaleDateString('hu-HU')+'\n'+(data.plan[dateKey(d)]||[]).map(m=>m.meal+': '+(byId.get(m.id)?.name||'')+' ('+m.people+' fő)').join('\n')).join('\n\n'))}
function addItems(arr){for(const i of mergeItems(arr)){const f=data.shop.find(x=>!x.done&&norm(x.name)===norm(i.name)&&x.unit===i.unit);if(f)f.qty+=i.qty;else data.shop.push({...i,done:false})}persist()}
function addRecipeShop(){const d=S.detail,r=byId.get(d.id);const ing=chosenIngredients(r,d.side,d.people);modal(modalHead('Bevásárlólista')+'<p class="muted">Melyik hozzávalókat szeretnéd hozzáadni?</p><div class="stack section">'+btn('Összes hozzávaló','commitShop(false)','primary block','cart')+btn('Csak a hiányzók (kamra alapján)','commitShop(true)','secondary block')+'</div>','addshop')}
function commitShop(missing){const d=S.detail,r=byId.get(d.id);let arr=chosenIngredients(r,d.side,d.people);if(missing)arr=arr.filter(i=>!data.pantry.some(p=>norm(i.name).includes(norm(p))));addItems(arr);closeModal();notify(arr.length+' hozzávaló a listán')}
function shop(){const done=data.shop.filter(i=>i.done).length;return title('Bevásárlólista','A receptjeid hozzávalói és saját tételeid egy helyen.')+'<div class="card"><div class="row between"><b>'+done+' / '+data.shop.length+' megvásárolva</b>'+tag('Helyben mentve')+'</div><div class="progress" style="margin:12px 0"><i style="width:'+(data.shop.length?done/data.shop.length*100:0)+'%"></i></div><form class="row" onsubmit="manualShop(event)"><input class="search-input grow" id="shopItem" required maxlength="100" placeholder="Új tétel..."><button class="iconbtn" type="submit" aria-label="Hozzáadás">'+ic('plus')+'</button></form><div class="spacer"></div>'+(data.shop.length?data.shop.map((i,k)=>'<div class="ingredient"><label class="'+(i.done?'checked':'')+'"><input type="checkbox" '+(i.done?'checked':'')+' onchange="checkShop('+k+',this.checked)"><span>'+esc(i.name)+'</span></label><b>'+esc(i.unit?qty(i.qty)+' '+i.unit:'')+'</b>'+ib('Mennyiség szerkesztése','editShop('+k+')','edit')+'</div>').join(''):empty('Receptből vagy saját tétellel töltsd fel a listát!','cart'))+'</div><div class="row section">'+btn('Megosztás','shareShop()','primary grow','share')+btn('Kipipáltak törlése','clearDone()','secondary grow')+'</div><div class="section">'+btn('Teljes lista törlése','clearShop()','outline danger block','trash')+'</div>'}
function manualShop(e){e.preventDefault();const s=$('shopItem').value.trim();if(s){addItems([{name:s,qty:1,unit:''}]);renderMain()}}
function checkShop(i,v){if(data.shop[i]){data.shop[i].done=v;persist();renderMain()}}
function editShop(i){const x=data.shop[i];if(!x)return;modal(modalHead('Tétel szerkesztése')+'<form onsubmit="saveShop(event,'+i+')"><label class="field">Megnevezés<input id="shopEditName" maxlength="100" value="'+esc(x.name)+'" required></label><div class="fields section"><label class="field">Mennyiség<input type="number" id="shopEditQty" min=".01" max="100000" step="any" value="'+x.qty+'" required></label><label class="field">Egység<input id="shopEditUnit" maxlength="20" value="'+esc(x.unit)+'"></label></div><button type="submit" class="btn primary block">Mentés</button></form>'+btn('Tétel törlése','deleteShop('+i+')','outline danger block','trash'))}
function saveShop(e,i){e.preventDefault();data.shop[i]={...data.shop[i],name:$('shopEditName').value.trim(),qty:clamp($('shopEditQty').value,.01,100000),unit:$('shopEditUnit').value.trim()};persist();closeModal();renderMain()}
function deleteShop(i){data.shop.splice(i,1);persist();closeModal();renderMain()}
function clearDone(){data.shop=data.shop.filter(x=>!x.done);persist();renderMain()}
function clearShop(){if(confirm('Biztosan törlöd az egész bevásárlólistát?')){data.shop=[];persist();renderMain()}}
function shareShop(){shareText('Bevásárlólista\n'+data.shop.filter(i=>!i.done).map(i=>'• '+i.name+(i.unit?' – '+qty(i.qty)+' '+i.unit:'')).join('\n'))}
function pantrySearch(){resetFilters();S.sort='pantry';S.filter.pantry=data.pantry.length>0;go('browse')}
function editRecipe(id=null){const r=id&&byId.get(id);modal(modalHead(r?'Recept szerkesztése':'Saját recept hozzáadása')+'<form onsubmit="saveOwn(event,'+(r?rId(r):'null')+')"><div class="fields"><label class="field full">Étel neve<input id="ownName" required maxlength="160" value="'+esc(r?.name||'')+'"></label>'+selectField('Konyha',cuisines,r?.cuisine||'Magyar','this.dataset.value=this.value')+selectField('Húsfajta',proteins,r?.protein||'Húsmentes','this.dataset.value=this.value')+'<label class="field">Idő (perc)<input id="ownTime" type="number" min="5" max="720" required value="'+(r?.time||30)+'"></label><label class="field">Alapadagszám<input id="ownBase" type="number" min="1" max="24" required value="'+(r?.base||2)+'"></label><label class="field">Fogás<select id="ownType">'+opts(types,r?.type||'Főétel')+'</select></label><label class="field">Elkészítés<select id="ownMethod">'+opts(methods,r?.method||'Tűzhely')+'</select></label><label class="field">Sütemény jellege<select id="ownBakeTaste">'+opts(bakingTastes,r?.bakery?.taste||'','Nem sütemény')+'</select></label><label class="field">Sütemény típusa<select id="ownBakeKind">'+opts(bakingKinds,r?.bakery?.kind||bakingKinds[0])+'</select></label><label class="field full">Fő ízesítés<select id="ownBakeFlavor">'+opts(bakingFlavors,r?.bakery?.flavor||'Egyéb')+'</select></label><label class="field full">Hozzávalók – soronként: név; mennyiség; egység<textarea id="ownIng" rows="6" required placeholder="csirkemell; 400; g\nrizs; 160; g">'+esc(r?r.ing.map(i=>i.name+'; '+i.qty+'; '+i.unit).join('\n'):'')+'</textarea></label><label class="field full">Elkészítés – lépésenként egy sor<textarea id="ownSteps" rows="6" required placeholder="Vágd fel a hozzávalókat...">'+esc(r?r.steps.join('\n'):'')+'</textarea></label><label class="field full"><span class="row"><input id="ownSpicy" type="checkbox" '+(r?.spicy?'checked':'')+'>Csípős</span></label></div><button type="submit" class="btn primary block">Recept mentése</button></form>','edit')}
function saveOwn(e,id){e.preventDefault();const sels=$('modal').querySelectorAll('select');const rows=$('ownIng').value.split('\n').filter(x=>x.trim()).map(line=>{const a=line.split(';');return {name:(a[0]||'').trim(),qty:Number((a[1]||'').trim().replace(',','.')),unit:(a[2]||'').trim()}});if(!rows.length||!rows.every(validIngredient)){notify('Minden hozzávaló formátuma: név; mennyiség; egység');return}const raw={id:id||uid(),name:$('ownName').value,cuisine:sels[0].value,protein:sels[1].value,time:+$('ownTime').value,base:+$('ownBase').value,type:$('ownType').value,method:$('ownMethod').value,spicy:$('ownSpicy').checked,bakery:$('ownBakeTaste').value?{taste:$('ownBakeTaste').value,kind:$('ownBakeKind').value,flavor:$('ownBakeFlavor').value}:null,ing:rows,steps:$('ownSteps').value.split('\n')};const r=sanitizeRecipe(raw);if(!r){notify('Ellenőrizd a recept mezőit!');return}const i=data.custom.findIndex(x=>x.id===r.id);if(i>=0)data.custom[i]=r;else data.custom.push(r);persist();rebuild();closeModal();go('saved');S.favMode='own';renderMain();openRecipe(r.id);notify('Saját recept mentve')}
function deleteOwn(id){if(!confirm('Végleg törlöd a saját receptet és a hozzá tartozó mentéseket?'))return;data.custom=data.custom.filter(r=>r.id!==id);data=sanitizeData(data);rebuild();persist();closeDetail();notify('Recept törölve')}
function showSettings(){const row=(icon,h,sub,action)=>'<button class="settings-row" onclick="'+action+'">'+ic(icon)+'<div class="grow"><b>'+h+'</b><p>'+sub+'</p></div>'+ic('chevron')+'</button>';modal(modalHead('Beállítások')+'<div class="fields"><label class="field">Megjelenés<select onchange="setTheme(this.value)">'+opts(['auto','light','dark'],data.theme).replace('>auto<','>Rendszer szerint<').replace('>light<','>Világos<').replace('>dark<','>Sötét<')+'</select></label><label class="field">Alap adag<select onchange="setPeople(this.value);showSettings()">'+peopleOpts(data.people)+'</select></label></div><div class="section">'+row('book','Segítség az alkalmazáshoz','Telepítés, offline használat, mentés','showPwaHelp()')+row('box','Kamra','Otthoni alapanyagok','showPantry()')+row('filter','Kizárt hozzávalók',data.exclude.length+' kizárás','showExclusions()')+row('clock','Konyhai időzítő','Visszaszámláló','showTimer()')+row('download','Biztonsági mentés','JSON fájl az összes személyes adatoddal','exportBackup()')+row('upload','Mentés visszaállítása','Korábban exportált JSON fájl','importBackup()')+row('book','Saját recept létrehozása','Saját hozzávalókkal és lépésekkel','editRecipe()')+row('trash','Tanult ízlés visszaállítása','A kedvenceket nem törli','resetTaste()')+'</div><p class="notice section">Mit főzzek? 3.1 · iPhone és web · '+recipes.length+' beépített receptötlet: '+recipes.filter(r=>r.origin==='klasszikus').length+' egyedileg írt klasszikus és '+recipes.filter(r=>r.origin==='variáció').length+' saját összeállítású variáció. A receptek és a lejárati dátum felismerése offline használhatók, regisztráció nélkül. A kamra és a mentések a készüléken maradnak.</p>','settings')}
function setTheme(t){data.theme=t;persist();theme()}
function showExclusions(){modal(modalHead('Kizárt hozzávalók')+'<p class="small muted">A szöveges szűrő kizárja a megadott alapanyagokat tartalmazó recepteket. Allergia esetén külön ellenőrizd a termékcímkéket is.</p><form class="row section" onsubmit="addExclusion(event)"><input id="excludeInput" class="search-input grow" required placeholder="Pl. mogyoró" maxlength="80"><button class="iconbtn" type="submit" aria-label="Hozzáadás">'+ic('plus')+'</button></form><div class="stack section">'+data.exclude.map((s,i)=>'<div class="row between"><span>'+esc(s)+'</span>'+ib('Törlés','removeExclusion('+i+')','trash')+'</div>').join('')+'</div>','exclude')}
function addExclusion(e){e.preventDefault();const x=$('excludeInput').value.trim();if(x&&!data.exclude.some(s=>norm(s)===norm(x))){data.exclude.push(x);persist()}showExclusions();renderMain()}
function removeExclusion(i){data.exclude.splice(i,1);persist();showExclusions();renderMain()}
function resetTaste(){if(confirm('Törlöd a tanult ízlésadatokat?')){data.scores={};persist();notify('Ízlésadatok visszaállítva')}}
function exportBackup(){const text=JSON.stringify(data,null,2),name='MitFozzek-mentes-'+today()+'.json';if(window.AndroidShare&&AndroidShare.exportBackup){AndroidShare.exportBackup(name,text);return}const blob=new Blob([text],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),3000)}
function importBackup(){if(window.AndroidShare&&AndroidShare.importBackup){AndroidShare.importBackup();return}$('importFile').click()}
window.receiveBackup=text=>{try{if(typeof text!=='string'||text.length>10*1024*1024)throw Error('A mentési fájl túl nagy vagy nem olvasható.');const parsed=sanitizeData(JSON.parse(text));if(!confirm('A mentés visszaállítása felülírja a jelenlegi személyes adataidat. Folytatod?'))return false;data=parsed;rebuild();persist();go('home');notify('Biztonsági mentés visszaállítva');return true}catch(e){notify('Nem sikerült megnyitni a mentést: '+e.message);return false}};
$('importFile').addEventListener('change',async e=>{const f=e.target.files[0];if(f){try{window.receiveBackup(await f.text())}catch{notify('A fájl nem olvasható.')}}e.target.value=''});
window.backupStatus=text=>notify(text);
function showTimer(){modal(modalHead('Konyhai időzítő')+'<div id="timerDisplay" class="timer">00:00</div><div class="fields"><label class="field">Perc<input id="timerMinutes" type="number" min="1" max="180" value="10"></label><div class="field"><span>Gyors indítás</span><div class="row"><button class="chip" onclick="startTimer(5)">5 p</button><button class="chip" onclick="startTimer(15)">15 p</button></div></div></div><div class="row">'+btn('Indítás','startTimer(+$(&quot;timerMinutes&quot;).value)','primary grow')+btn('Megállítás','stopTimer()','secondary grow')+'</div><p class="small muted">Az időzítő az alkalmazáson belül működik; háttérben vagy lezárt kijelzőn a jelzés nem garantált.</p>','timer');tickTimer()}
function startTimer(n){n=clamp(n,1,180);S.timerEnd=Date.now()+n*60000;S.timerLeft=n*60;tickTimer()}
function stopTimer(){S.timerEnd=0;S.timerLeft=0;tickTimer()}
function tickTimer(){let seconds=S.timerEnd?Math.max(0,Math.ceil((S.timerEnd-Date.now())/1000)):0;if(S.timerEnd&&seconds<=0){S.timerEnd=0;notify('Lejárt a konyhai időzítő!');try{navigator.vibrate?.([200,100,200])}catch{}}const el=$('timerDisplay');if(el)el.textContent=String(Math.floor(seconds/60)).padStart(2,'0')+':'+String(seconds%60).padStart(2,'0')}
setInterval(tickTimer,500);
window.appBack=()=>{if(S.modal){closeModal();return true}if(S.detail){closeDetail();return true}if(S.tab!=='home'){go('home');return true}return false};
